import java.nio.file.*;import java.util.*;import java.io.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import org.objectweb.asm.util.*;
public class HudResetClassPatch{
 static ClassNode read(byte[] b,int f){var c=new ClassNode();new ClassReader(b).accept(c,f);return c;}
 static String key(MethodNode m){return m.name+m.desc;}
 static String norm(MethodNode m){m.maxStack=0;m.maxLocals=0;var p=new Textifier();m.accept(new TraceMethodVisitor(p));var s=new StringWriter();p.print(new PrintWriter(s));return s.toString();}
 public static void main(String[]a)throws Exception{byte[] before=Files.readAllBytes(Path.of(a[0]));var b=read(before,0);var n=read(Files.readAllBytes(Path.of(a[1])),0);boolean settings=b.name.endsWith("/SettingsScreen");var replace=settings?Set.of("method_25394","method_25402"):Set.of("reset");var added=new HashSet<String>();var changed=new HashSet<String>();
 if(settings){var old=read(before,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);var now=read(Files.readAllBytes(Path.of(a[1])),ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(var m:old.methods){if(replace.contains(m.name))continue;var x=now.methods.stream().filter(v->key(v).equals(key(m))).findFirst().orElseThrow();if(!norm(m).equals(norm(x)))throw new IllegalStateException("Source baseline differs in unrelated settings method: "+key(m));}}
 for(var m:n.methods){boolean take=replace.contains(m.name)||settings&&(m.name.equals("confirmHudReset")||m.name.startsWith("lambda$confirmHudReset$"))||!settings&&m.name.startsWith("lambda$reset$");if(!take)continue;var old=b.methods.stream().filter(x->key(x).equals(key(m))).findFirst().orElse(null);if(old!=null){if(!replace.contains(m.name))throw new IllegalStateException("new method collision");b.methods.remove(old);changed.add(key(m));}else added.add(key(m));b.methods.add(m);}
 var cw=new ClassWriter(ClassWriter.COMPUTE_MAXS);b.accept(cw);byte[] out=cw.toByteArray();var old=read(before,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);var after=read(out,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);int kept=0;for(var m:old.methods){if(changed.contains(key(m)))continue;var x=after.methods.stream().filter(v->key(v).equals(key(m))).findFirst().orElseThrow();if(!norm(m).equals(norm(x)))throw new IllegalStateException("Unrelated method changed: "+key(m));kept++;}for(var m:read(out,0).methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(b.name,m);Files.write(Path.of(a[2]),out);System.out.println("PASS "+b.name+" preserved="+kept+" changed="+changed+" added="+added);
 }
}